package cli

import (
	"archive/tar"
	"bytes"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
	"testing"
	"time"

	"github.com/spf13/cobra"
)

func TestSemanticIndexCommandParsesGraphProviderFlags(t *testing.T) {
	cmd := newSemanticIndexCommand(Options{})
	if err := cmd.ParseFlags([]string{
		"--skip-graph",
		"--graph-timeout", "17m",
		"--graph-inactivity-timeout", "42s",
	}); err != nil {
		t.Fatalf("parse graph provider flags: %v", err)
	}

	skipGraph, err := cmd.Flags().GetBool("skip-graph")
	if err != nil || !skipGraph {
		t.Fatalf("skip-graph = %v, err = %v", skipGraph, err)
	}
	timeout, err := cmd.Flags().GetDuration("graph-timeout")
	if err != nil || timeout != 17*time.Minute {
		t.Fatalf("graph-timeout = %s, err = %v", timeout, err)
	}
	inactivityTimeout, err := cmd.Flags().GetDuration("graph-inactivity-timeout")
	if err != nil || inactivityTimeout != 42*time.Second {
		t.Fatalf("graph-inactivity-timeout = %s, err = %v", inactivityTimeout, err)
	}
}

func TestSemanticIndexStoresProviderSnapshotAndManifest(t *testing.T) {
	repoDir := t.TempDir()
	env := semanticTestEnv(t, repoDir)
	runner := semanticFixtureRunner(repoDir, semanticFixtureSnapshot("1.0"))
	cmd := &cobra.Command{Use: "index"}

	if err := runSemanticIndex(cmd.Context(), cmd, Options{
		Version: "test",
		Env:     env,
		Runner:  runner,
		Now:     func() time.Time { return time.Date(2026, 5, 31, 12, 0, 0, 0, time.UTC) },
	}, semanticIndexOptions{graphBinary: "entire"}, repoDir); err != nil {
		t.Fatalf("index: %v", err)
	}

	manifestPath := filepath.Join(env.PluginDataDir, repoStoreDirName, "gh", "example", "repo", exportManifestFileName)
	data, err := os.ReadFile(manifestPath)
	if err != nil {
		t.Fatalf("read manifest: %v", err)
	}
	var manifest exportManifest
	if err := json.Unmarshal(data, &manifest); err != nil {
		t.Fatalf("parse manifest: %v", err)
	}
	semantic := manifest.Sources.Semantic
	if semantic == nil {
		t.Fatalf("semantic source missing: %+v", manifest.Sources)
	}
	if semantic.Provider != "entire-graph" || semantic.SchemaVersion != "1.0" {
		t.Fatalf("provider metadata = %+v", semantic)
	}
	if semantic.Symbols != 1 || semantic.Relations != 1 || semantic.Files != 1 {
		t.Fatalf("counts = files %d symbols %d relations %d", semantic.Files, semantic.Symbols, semantic.Relations)
	"encoding/json"
	"strings"
)

const (
	// SchemaVersion is the frozen delta-document version.
	SchemaVersion = "1.0"
	// Producer names the tool that computed a delta document.
	Producer = "entire-graph"

	// ForwardKey is the git-meta key holding a commit's delta document.
	ForwardKey = "brain:entities"
	// reverseKeyPrefix namespaces the entity -> commits reverse list.
	reverseKeyPrefix = "brain:entity:"
	// aliasKeyPrefix namespaces the old-key -> new-key rename/move alias.
	aliasKeyPrefix = "brain:entity-alias:"
	// windowKeyPrefix namespaces the per-branch INDEXED WINDOW record: the
	// floor and tip of one contiguous, fully-indexed first-parent range.
	windowKeyPrefix = "brain:entities-window:"

	// EmptyTreeSHA is git's canonical empty tree. It is the diff base for a root
	// commit, so the very first commit's entities are indexed as `added` rather
	// than skipped.
	EmptyTreeSHA = "4b825dc642cb6eb9a060e54bf8d69288fbee4904"
)

