	Profile                 string            `json:"profile,omitempty"`
	RelationSet             []string          `json:"relation_set,omitempty"`
	SkippedRelationFamilies []string          `json:"skipped_relation_families,omitempty"`
	Completeness            json.RawMessage   `json:"completeness,omitempty"`
	ProfileLimits           json.RawMessage   `json:"profile_limits,omitempty"`
	Stats                   json.RawMessage   `json:"stats,omitempty"`
	Warnings                []semanticWarning `json:"warnings,omitempty"`
	PartialFailures         []semanticWarning `json:"partial_failures,omitempty"`
}

// semanticStreamCounts tracks records observed while streaming. These are the
// "what came over the wire (after filtering)" counters used for progress and
// audit; the persisted manifest counts live in semanticCounts.
// as the other writer runs. Contention costs a skipped tick instead.
func refreshEntityIndexQuietly(ctx context.Context, opts Options, repoDir string) error {
	// A hard deadline, not just a commit budget: the provider runs once per new
	// commit, and a watch tick must stay a tick even on a repository where the
	// semantic diff is slow.
	ctx, cancel := context.WithTimeout(ctx, entitiesFreshnessTimeout)
	defer cancel()
	_, _, store, err := openEntityIndexStore(ctx, opts, repoDir)
	if err != nil {
		return err
	}
	result, err := entityindex.Build(ctx, opts.Runner, store, entityindex.BuildOptions{
		RepoDir:     repoDir,
		GraphBinary: "entire",
		Limit:       entitiesFreshnessCommits,
		NonBlocking: true,
		Now:         opts.Now,
	})
	if err != nil {
		return err
	}
	if result.Indexed == 0 {
		return nil
	}
	// Refresh the derived join so the next query does not pay for it.
	_, err = loadEntityIndexView(ctx, opts, repoDir)
	return err
}

