  for _,c:=range cs {
   base:=c.Parent;if base==""{base=EmptyTreeSHA}
   r.set(graphDiffKey(base,c.SHA),graphOutput(base,c.SHA,graphFileChange{Path:"a.js",Changes:[]graphEntityChange{{Type:"added",Kind:"method",Name:"A.helper",AfterStartLine:3}}}))
   r.set("git log -1 "+gitLogFormat+" "+c.SHA,fmt.Sprintf("%s\x00%s\x00%s\x00%s\x1e",c.SHA,c.Parent,c.CommittedAt.Format("2006-01-02T15:04:05Z07:00"),c.Message))
  }
  if _,err:=Build(ctx,r,store,BuildOptions{RepoDir:testRepoDir,Now:fixedNow()});err!=nil{t.Fatal(err)}
  _,err:=store.Update(1,func(st gitmeta.State)(gitmeta.State,error){return st.Apply(gitmeta.Mutation{Op:gitmeta.OpSetString,Target:projectTarget,Key:"brain:authored-fact",Value:"keep me"}),nil});if err!=nil{t.Fatal(err)}
  before, _:=store.Tip()
  if err:=CheckIdentity(store,"scope-1");err==nil{t.Fatal("upgrade accepted without migration")}
  for _,c:=range cs {base:=c.Parent;if base==""{base=EmptyTreeSHA};r.set(graphDiffKey(base,c.SHA),graphOutput(base,c.SHA,graphFileChange{Path:"a.js",Changes:[]graphEntityChange{{Type:"added",Kind:"function",Name:"A.m.helper",AfterStartLine:3}}}))}
  r.set("entire graph version --json",`{"identity_revision":"scope-1"}`)
  if fail {r.fail(graphDiffKey(cs[0].SHA,cs[1].SHA),errors.New("provider stopped"))}
  result,err:=Migrate(ctx,r,store,BuildOptions{RepoDir:testRepoDir,IdentityRevision:"scope-1",Now:fixedNow()})
  if fail {if err==nil{t.Fatal("accepted partial migration")};after,_:=store.Tip();if after!=before{t.Fatal("failed migration changed store")};return}
  if err!=nil{t.Fatal(err)};if result.Indexed!=2{t.Fatal(result)}
  if err:=CheckIdentity(store,"scope-1");err!=nil{t.Fatal(err)}
  snap:=loadSnapshot(t,store)
  if got:=snap.Commits("a.js#function#A.m.helper");!reflect.DeepEqual(got,[]string{cs[0].SHA,cs[1].SHA}){t.Fatalf("history=%v",got)}
  if got:=snap.Commits("a.js#method#A.helper");len(got)!=0{t.Fatalf("stale reverse entries: %v",got)}
  if value,ok,err:=store.ReadString(projectTarget,"brain:authored-fact");err!=nil||!ok||value!="keep me"{t.Fatal("authored memory changed")}
  w,ok:=snap.Window("main");if !ok||w.Floor!=cs[0].SHA||w.Tip!=cs[1].SHA{t.Fatal("coverage changed",w)}
  for _,c:=range cs{d,ok:=snap.Delta(c.SHA);if !ok||d.Head!=c.SHA||d.IdentityRevision!="scope-1"{t.Fatal("lost forward provenance",d)}}
 }) }
}
