	baseReader := gitutil.NewLimitedFileReader(ctx, objectRepo, pinnedBase, maxDiffFileBytes)
	headReader := gitutil.NewLimitedFileReader(ctx, objectRepo, pinnedHead, maxDiffFileBytes)
	baseReader.SetDeadline(deadline)
	headReader.SetDeadline(deadline)
	defer func() {
		_ = baseReader.Close()
		_ = headReader.Close()
	}()
	// SchemaVersion is set here, at the one place a content-bearing Result is
	// constructed; every caller (AnalyzeGitRange, AnalyzeCheckpoint, and the
	// diff/analyze CLI handlers that call through them) inherits it.
	result := Result{Base: base, Head: head, SchemaVersion: SchemaVersion}
	result.Warnings = append(result.Warnings, policyWarnings...)
	var deltas []*fileDelta
	appendBudgetWarnings := func(start int) {
		for _, skipped := range changed[start:] {
	}
	oldName := change.OldName
	if oldName == name {
		oldName = ""
	}
	startLine := change.AfterStartLine
	if startLine == 0 {
		// A removal has no after-image; keep the pre-change line so the record
		// still points somewhere useful.
		startLine = change.BeforeStartLine
	}
	return EntityDelta{
		Change:       normalizeChange(change.Type),
		Kind:         change.Kind,
		Name:         name,
		OldName:      oldName,
		Path:         path,
		OldPath:      oldPath,
		Signature:    change.NewSignature,
		OldSignature: change.OldSignature,
		StartLine:    startLine,
	}, true
}

// normalizeChange maps the provider's change vocabulary onto the contract's.
// Anything unrecognized folds to "modified": an unknown change type still means
// the entity was touched by this commit, which is the whole question the index
// answers, so folding is strictly better than dropping the record.

